package com.codearena.submission;
import com.codearena.common.api.ApiResponse; import com.codearena.common.domain.*; import com.codearena.problem.*; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.http.*; import org.springframework.lang.NonNull; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.transaction.annotation.Transactional; import com.codearena.contest.*;
@RestController @RequestMapping("/api/v1/submissions") public class SubmissionController { final SubmissionRepository repo;final ProblemRepository problems;final RabbitTemplate rabbit; final ContestRepository contests; final ContestParticipantRepository participants; SubmissionController(SubmissionRepository r,ProblemRepository p,RabbitTemplate q,ContestRepository c,ContestParticipantRepository cp){repo=r;problems=p;rabbit=q;contests=c;participants=cp;} record Create(@NotNull @NonNull UUID problemId,UUID contestId,@NotBlank @Size(max=32) String language,@NotBlank @Size(max=262144) String sourceCode){} @PostMapping @Transactional @ResponseStatus(HttpStatus.ACCEPTED) ApiResponse<SubmissionView> create(@AuthenticationPrincipal String userId,@RequestBody @jakarta.validation.Valid Create c){var p=problems.findById(c.problemId).filter(x->x.published).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Problem unavailable"));if(!p.supportedLanguages.contains(c.language))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported language");if(c.contestId!=null){var contest=contests.findById(c.contestId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Contest unavailable"));if(!contest.status.equals("ACTIVE")||java.time.Instant.now().isBefore(contest.startsAt)||java.time.Instant.now().isAfter(contest.endsAt)||!participants.existsById(new ContestParticipantKey(c.contestId,UUID.fromString(userId))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Contest is not accepting this submission");}var s=new Submission();s.studentId=UUID.fromString(userId);s.problemId=c.problemId;s.contestId=c.contestId;s.language=c.language;s.sourceCode=c.sourceCode;s.status=SubmissionStatus.QUEUED;s=repo.save(s);try{rabbit.convertAndSend("submission.exchange","submission.created",new SubmissionJob(s.id));}catch(RuntimeException publishFailure){s.status=SubmissionStatus.CREATED;repo.save(s);throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Submission queue unavailable");}return ApiResponse.of(SubmissionView.from(s));} @GetMapping ApiResponse<Page<SubmissionView>> mine(@AuthenticationPrincipal String id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){var pageable=PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)));return ApiResponse.of(repo.findByStudentId(UUID.fromString(id),pageable).map(SubmissionView::from));} @GetMapping("/{id}") ApiResponse<SubmissionView> get(@AuthenticationPrincipal String uid,@PathVariable @NonNull UUID id){var s=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!s.studentId.equals(UUID.fromString(uid)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return ApiResponse.of(SubmissionView.from(s));} public record SubmissionJob(UUID submissionId){} public record SubmissionView(UUID id,UUID problemId,UUID contestId,String language,SubmissionStatus status,Verdict verdict,Long executionTimeMs,Long memoryUsageKb,Integer score,java.time.Instant submittedAt,java.time.Instant completedAt){static SubmissionView from(Submission s){return new SubmissionView(s.id,s.problemId,s.contestId,s.language,s.status,s.verdict,s.executionTimeMs,s.memoryUsageKb,s.score,s.submittedAt,s.completedAt);}} }
